    public static void test_proxy_plumbing(Object monkeypatch) {
        /* PROXY_URL is honored: SOCKS manager gets the exact URL; unset -> plain pool. */
        Map<String, Object> seen = new HashMap<>();
        monkeypatch.setattr(dl, "SOCKSProxyManager", (/* ** */ kw) -> seen.putAll(kw), /* raising = */ false);
        monkeypatch.setattr(dl, "PROXY_URL", "socks5://user:pass@localhost:1080");
        dl.create_pool();
        assert seen.get("proxy_url") == "socks5://user:pass@localhost:1080";
        monkeypatch.setattr(dl, "PROXY_URL", null);
        assert dl.create_pool() instanceof dl.urllib3.PoolManager;
        // proxy disables SSRF filtering on both backends
        assert dl._ssrf_active(DEFAULT_CONFIG) == true;
        monkeypatch.setattr(dl, "PROXY_URL", "socks5://localhost:1080");
        assert dl._ssrf_active(DEFAULT_CONFIG) == false;
    }

